const liveDiagnostics=()=>presentation.mode!=='headless';
let settings={...DEFAULT_PARKING},brain:ParkingBrain,session:ParkingSession,initialScene:ParkingScene,sourceParent:unknown=null,stagedRacer:BrainSnapshot|null=null,stagedParent:unknown=null,stagedMetadata:ParkingBrain['metadata'],racerEyes:VisionModel|null=null;
let view3d:ParkingView3D|null=null;
let running=false,busy=false,cancelled=false,report:ParkingTrainingReport|null=null,ghosts:ParkingSession[]=[],mapPerspective=true,lastPreview=-Infinity,lastPing=-1;
const effectTimes=new WeakMap<object,number>();
const lines:string[]=[],keys=new Set<string>(),demonstrations:{inputs:number[];target:Action}[]=[];
function status(text:string,error=false){el('status').textContent=text;el('status').classList.toggle('error',error);}
function log(text:string){lines.push(`[${session?(session.episode.tick/30).toFixed(2):'0.00'}s] ${text}`);if(lines.length>600)lines.shift();el('logs').textContent=lines.join('\n');}
function save(name:string,text:string){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function setRunning(on:boolean){running=on&&!session.done;el('run').textContent=running?'Ⅱ Pause':'▶ Run fly';}
function safe(action:()=>void|Promise<void>){return()=>{try{const value=action();if(value instanceof Promise)value.catch(e=>status((e as Error).message,true));}catch(e){status((e as Error).message,true);}};}
function readSettings(){return validateParkingSettings({...settings,lesson:val('lesson') as Lesson,cue:val('cue') as ParkingSettings['cue'],phase:val('phase') as ParkingSettings['phase'],seed:num('seed'),maxTicks:num('seconds')*30,crashWeight:num('crash-weight'),traffic:num('traffic-count'),pedestrians:num('pedestrian-count'),cars:checked('cars'),shapeJitter:checked('jitter'),remember:checked('remember'),delayReward:checked('delay-reward'),rewardDelaySeconds:num('reward-delay'),sonarOn:checked('sonar-on'),cameraMount:val('camera-mount') as ParkingSettings['cameraMount'],bayAlignment:checked('bay-alignment'),floor:val('floor') as ParkingSettings['floor'],approachReward:checked('approach-reward'),approachRadius:num('approach-radius'),progressPenalty:checked('progress-penalty'),reverseReward:checked('reverse-reward'),pathReward:checked('path-reward'),showCoach:checked('show-coach'),slowDriving:checked('slow-driving'),slowMode:val('slow-mode') as ParkingSettings['slowMode'],slowSpeedCm:num('slow-speed'),slowWeight:num('slow-weight'),slowZoneRadius:num('slow-zone'),strictCrash:checked('strict-crash'),parkedOffset:checked('parked-offset'),layout:val('parking-layout'),selection:val('selection') as ParkingSettings['selection'],scoreWeight:num('score-weight'),speedWeight:num('speed-weight'),safetyWeight:num('safety-weight')});}
function fill(){for(const [id,v] of Object.entries({selection:settings.selection,'score-weight':settings.scoreWeight,'speed-weight':settings.speedWeight,'safety-weight':settings.safetyWeight,'parking-layout':settings.layout,lesson:settings.lesson,cue:settings.cue,phase:settings.phase,seed:settings.seed,seconds:settings.maxTicks/30,'crash-weight':settings.crashWeight,'traffic-count':settings.traffic,'pedestrian-count':settings.pedestrians,swarm:brain.visual.layout,'memory-size':brain.memory.count,'reward-delay':settings.rewardDelaySeconds,'camera-mount':settings.cameraMount,floor:settings.floor,'approach-radius':settings.approachRadius,'slow-mode':settings.slowMode,'slow-speed':settings.slowSpeedCm,'slow-weight':settings.slowWeight,'slow-zone':settings.slowZoneRadius}))el<HTMLInputElement>(id).value=String(v);for(const [id,v] of Object.entries({'strict-crash':settings.strictCrash,'parked-offset':settings.parkedOffset,remember:settings.remember,cars:settings.cars,jitter:settings.shapeJitter,normalize:brain.visual.normalize,'delay-reward':settings.delayReward,'sonar-on':settings.sonarOn,'bay-alignment':settings.bayAlignment,'approach-reward':settings.approachReward,'progress-penalty':settings.progressPenalty,'reverse-reward':settings.reverseReward,'path-reward':settings.pathReward,'show-coach':settings.showCoach,'slow-driving':settings.slowDriving}))el<HTMLInputElement>(id).checked=v;el<HTMLInputElement>('reward-delay').disabled=!settings.delayReward;el('completion-note').textContent=settings.delayReward?`Release controls → 1 s stop + ${settings.rewardDelaySeconds} s delay`:'Fit → stop → hold 1 second';el('lesson-help').textContent=LESSONS.find(l=>l.id===settings.lesson)!.detail;el('crash-label').textContent=Math.round(settings.crashWeight*100)+'%';el('criteria').innerHTML=`<option>${['arrival','exit','switch'].includes(settings.lesson)?'Yellow area + stop; heading ignored':'Entire body + orientation + stop'}</option>`;}
function persistPreferences(){try{localStorage.setItem('flykart-parking-preferences',JSON.stringify({settings,visual:brain.visual,memory:brain.memory}));}catch{}}
function rebuild(scene?:ParkingScene){if(busy)throw Error('Stop the training job before editing a lot.');setRunning(false);const remembered=settings.remember&&session&&JSON.stringify(session.memory.settings)===JSON.stringify(brain.memory)?session.memory:undefined;initialScene=scene?validateParkingScene(scene):generateParking(settings);session=new ParkingSession(settings,brain,{scene:initialScene,memory:remembered,diagnostics:liveDiagnostics});lastPing=-1;ghosts=[];fill();render();persistPreferences();log(`Lot ${settings.seed} · ${settings.lesson} · ${settings.cue} cue · ${settings.phase} phase · ${remembered?'retained':'fresh'} visual memory`);}
function brainText(){return parkingBrainText(brain,session.memory,settings,sourceParent,report?.brain===brain.controller?report:null);}
