function chooseBay(x:number,z:number){if(busy)return;const bay=initialScene.bays.find(b=>!b.occupied&&Math.hypot(b.x-x,b.z-z)<.23);if(bay){try{if(settings.lesson!=='arrival'&&Math.hypot(bay.x-initialScene.start.x,bay.z-initialScene.start.z)<.3)throw Error('Choose a different bay from the starting space.');const next=structuredClone(initialScene);next.target={...bay};rebuild(next);status('Vacant bay selected. Geometry retained; live run restarted.');}catch(e){status((e as Error).message,true);}}}
function safePointer(event:PointerEvent){const canvas=el<HTMLCanvasElement>('lot'),r=canvas.getBoundingClientRect(),scale=Math.min(canvas.width/6.4,canvas.height/6.4);chooseBay(((event.clientX-r.left)/r.width*canvas.width-canvas.width/2)/scale,((event.clientY-r.top)/r.height*canvas.height-canvas.height/2)/scale);}
function fitMonitorStack(){const monitors=document.querySelector<HTMLElement>('.monitors')!;if(innerWidth<=1050){monitors.style.removeProperty('--parking-preview-height');return;}const cards=Array.from(monitors.querySelectorAll<HTMLElement>('.monitor')).filter(c=>!c.hidden);const overhead=cards.reduce((n,card)=>n+card.getBoundingClientRect().height-card.querySelector('canvas')!.getBoundingClientRect().height,0)+24;const available=innerHeight-monitors.getBoundingClientRect().top-8;monitors.style.setProperty('--parking-preview-height',Math.max(60,Math.min(150,Math.floor((available-overhead)/Math.max(1,cards.length))))+'px');}
